import { describe, expect, it } from "vitest";
import { NO_ACTIONS, NO_CONDITIONS } from "../../core/filters";
import {
  SieveSyntaxError,
  autoReplyOf,
  filterChunks,
  folderId,
  insertFilter,
  parseScript,
  removeFilter,
  reorderFilters,
  replaceFilter,
  ruleText,
  setVacation,
  toggledCustom,
  vacationText,
  withRequires,
  writeScript,
  type SieveRule,
} from "./script";

/** Roundcube's rules, hand-written ones, comments: as found on servers. */
const SCRIPT = [
  "# Generated by Roundcube",
  'require ["fileinto","imap4flags","copy","body"];',
  "# rule:[Newsletters]",
  'if anyof (header :contains "from" "news@shop.at")',
  "{",
  '\tfileinto "Shopping";',
  "\tstop;",
  "}",
  "# rule:[Boss]",
  'if false # allof (header :contains "from" ["boss@work.at", "chef@work.at"], header :contains "subject" "urgent")',
  "{",
  '\taddflag "\\\\Flagged";',
  "}",
  "/* hand-written */",
  'if header :contains "X-Spam-Flag" "YES" {',
  '  fileinto "Junk";',
  "  stop;",
  "}",
  "if size :over 5M {",
  '    redirect :copy "big@example.org";',
  "}",
  "",
].join("\n");

const rule = (overrides: Partial<SieveRule> = {}): SieveRule => ({
  enabled: true,
  conditions: { ...NO_CONDITIONS, from: ["anna@example.org"] },
  actions: { ...NO_ACTIONS, markRead: true },
  extras: [],
  ...overrides,
});

describe("reading Sieve scripts", () => {
  it("gives back the exact text when nothing changes", () => {
    expect(writeScript(parseScript(SCRIPT))).toBe(SCRIPT);
    const crlf = SCRIPT.replace(/\n/g, "\r\n");
    const document = parseScript(crlf);
    expect(document.eol).toBe("\r\n");
    expect(writeScript(document)).toBe(crlf);
  });

  it("reads Roundcube's rules, switched-off ones too, and keeps others as custom", () => {
    const filters = filterChunks(parseScript(SCRIPT));
    expect(filters.map((f) => f.kind)).toEqual([
      "rule",
      "rule",
      "custom",
      "rule",
    ]);
    const [news, boss, spam, big] = filters;
    expect(news).toMatchObject({
      kind: "rule",
      rule: {
        name: "Newsletters",
        enabled: true,
        conditions: { from: ["news@shop.at"] },
        actions: { moveTo: folderId("Shopping"), stop: true },
        extras: [],
      },
    });
    expect(boss).toMatchObject({
      kind: "rule",
      rule: {
        name: "Boss",
        enabled: false,
        conditions: {
          from: ["boss@work.at", "chef@work.at"],
          subject: ["urgent"],
        },
        actions: { star: true },
      },
    });
    expect(spam).toMatchObject({
      kind: "custom",
      enabled: true,
      code: 'if header :contains "X-Spam-Flag" "YES" {\n  fileinto "Junk";\n  stop;\n}',
    });
    expect(big).toMatchObject({
      kind: "rule",
      rule: {
        conditions: { size: { compare: "larger", bytes: 5 * 1024 * 1024 } },
        actions: { forwardTo: ["big@example.org"] },
      },
    });
  });

  it("changes only the rule that changed", () => {
    const document = parseScript(SCRIPT);
    const [news] = filterChunks(document);
    if (news?.kind !== "rule") throw new Error("no rule");
    const changed = {
      ...news.rule,
      conditions: { ...news.rule.conditions, from: ["deals@shop.at"] },
    };
    const { text } = ruleText(changed, document.eol);
    const written = writeScript(
      replaceFilter(document, 0, { kind: "rule", text, rule: changed }),
    );
    expect(written).toBe(
      SCRIPT.replace(
        '# rule:[Newsletters]\nif anyof (header :contains "from" "news@shop.at")\n{\n\tfileinto "Shopping";\n\tstop;\n}',
        '# rule:[Newsletters]\nif header :contains "from" "deals@shop.at"\n{\n\tfileinto "Shopping";\n\tstop;\n}',
      ),
    );
  });

  it("reads every condition and action it shows, and writes them back the same", () => {
    const all: SieveRule = {
      name: "Everything",
      enabled: true,
      conditions: {
        from: ["a@x.org", 'Quote "me"'],
        to: ["me@x.org"],
        subject: ["back\\slash"],
        words: ["invoice"],
        notWords: ["draft", "test"],
        hasAttachment: true,
        size: { compare: "smaller", bytes: 1536 },
      },
      actions: {
        ...NO_ACTIONS,
        markRead: true,
        star: true,
        forwardTo: ["a@x.org", "b@x.org"],
        moveTo: folderId("INBOX/Rechnungen"),
        stop: true,
      },
      extras: [],
    };
    const { text, needs } = ruleText(all, "\n");
    expect(needs.sort()).toEqual(
      ["body", "body", "copy", "copy", "fileinto", "imap4flags", "mime"].sort(),
    );
    const [read] = filterChunks(parseScript(text));
    expect(read).toMatchObject({ kind: "rule", rule: all });
  });

  it("knows Trash, and keeps actions it doesn't show (“and more”)", () => {
    const script = [
      'if address :is "from" "x@y.org" {',
      '  fileinto "Trash";',
      "}",
      'if header :contains ["cc", "to"] "list@x.org" {',
      '  fileinto :copy "Archive";',
      '  addflag "$label1";',
      "  keep;",
      "}",
      "",
    ].join("\n");
    const [trash, list] = filterChunks(parseScript(script, { trash: "Trash" }));
    expect(trash).toMatchObject({
      kind: "rule",
      rule: { conditions: { from: ["x@y.org"] }, actions: { trash: true } },
    });
    expect(list).toMatchObject({
      kind: "rule",
      rule: {
        conditions: { to: ["list@x.org"] },
        extras: ['fileinto :copy "Archive";', 'addflag "$label1";', "keep;"],
      },
    });
    if (list?.kind !== "rule") throw new Error("no rule");
    const { text } = ruleText(
      { ...list.rule, actions: { ...list.rule.actions, markRead: true } },
      "\n",
    );
    expect(text).toBe(
      [
        'if header :contains ["to", "cc"] "list@x.org"',
        "{",
        '\taddflag "\\\\Seen";',
        '\tfileinto :copy "Archive";',
        '\taddflag "$label1";',
        "\tkeep;",
        "}",
      ].join("\n"),
    );
  });

  it("keeps an if with elsif or else, and tests it can't show, as custom rules", () => {
    const script = [
      'if header :contains "subject" "a" { stop; } elsif true { keep; } else { discard; }',
      'if header :regex "subject" "^x" { stop; }',
      'if anyof (header :contains "from" "a", header :contains "from" "b") { stop; }',
      "",
    ].join("\n");
    const filters = filterChunks(parseScript(script));
    expect(filters.map((f) => f.kind)).toEqual(["custom", "custom", "custom"]);
    expect(filters[0]).toMatchObject({
      code: 'if header :contains "subject" "a" { stop; } elsif true { keep; } else { discard; }',
    });
    expect(writeScript(parseScript(script))).toBe(script);
  });

  it("switches custom rules off and on like Roundcube", () => {
    const document = parseScript(
      '# rule:[Spam]\nif header :contains "X-Spam" "YES" { fileinto "Junk"; }\n',
    );
    const [custom] = filterChunks(document);
    if (custom?.kind !== "custom") throw new Error("no custom rule");
    expect(custom.name).toBe("Spam");
    const off = toggledCustom(custom, false, "\n");
    expect(off).toBe(
      '# rule:[Spam]\nif false # header :contains "X-Spam" "YES"\n{ fileinto "Junk"; }',
    );
    const [disabled] = filterChunks(parseScript(`${off ?? ""}\n`));
    if (disabled?.kind !== "custom") throw new Error("no custom rule");
    expect(disabled.enabled).toBe(false);
    expect(toggledCustom(disabled, true, "\n")).toBe(
      '# rule:[Spam]\nif header :contains "X-Spam" "YES"\n{ fileinto "Junk"; }',
    );
  });

  it("switches off a custom rule whose test spans lines with allof (false, …)", () => {
    const script =
      'if anyof (header :contains "a" "1",\n          header :contains "b" "2") { stop; }\n';
    const [custom] = filterChunks(parseScript(script));
    if (custom?.kind !== "custom") throw new Error("no custom rule");
    const off = toggledCustom(custom, false, "\n") ?? "";
    expect(off).toBe(
      'if allof (false, anyof (header :contains "a" "1",\n          header :contains "b" "2")) { stop; }',
    );
    const [disabled] = filterChunks(parseScript(off));
    if (disabled?.kind !== "custom") throw new Error("no custom rule");
    expect(disabled.enabled).toBe(false);
    expect(toggledCustom(disabled, true, "\n")).toBe(script.trimEnd());
  });

  it("refuses what isn't Sieve", () => {
    expect(() => parseScript('if header :contains "a" "b {')).toThrow(
      SieveSyntaxError,
    );
    expect(() => parseScript("if true { stop; ")).toThrow(SieveSyntaxError);
  });

  it("reads multi-line text strings", () => {
    const script = [
      'require "vacation";',
      'vacation :days 3 :subject "Away" text:',
      "I'm away.",
      "..dots stay",
      ".",
      ";",
      "",
    ].join("\r\n");
    const document = parseScript(script);
    expect(autoReplyOf(document)).toEqual({
      enabled: true,
      subject: "Away",
      text: "I'm away.\n.dots stay",
      contactsOnly: false,
    });
    expect(writeScript(document)).toBe(script);
  });
});

describe("the automatic reply", () => {
  it("reads Roundcube's vacation rule with its days", () => {
    const script = [
      'require ["vacation","date","relational"];',
      "# rule:[Out of office]",
      'if allof (currentdate :zone "+0100" :value "ge" "iso8601" "2026-11-01T00:00:00+01:00", currentdate :zone "+0100" :value "le" "iso8601" "2026-11-10T23:59:59+01:00")',
      "{",
      '\tvacation :days 1 :subject "Away" :from "me@x.org" "Back on the 11th.";',
      "}",
      "",
    ].join("\n");
    const document = parseScript(script);
    expect(filterChunks(document)).toEqual([]);
    expect(autoReplyOf(document)).toEqual({
      enabled: true,
      start: "2026-11-01",
      end: "2026-11-10",
      subject: "Away",
      text: "Back on the 11th.",
      contactsOnly: false,
    });
  });

  it("writes it at the top with the extensions it needs, and switches it off keeping its text", () => {
    const document = parseScript(SCRIPT);
    const vacation = {
      enabled: true,
      start: "2026-12-20",
      end: "2027-01-06",
      subject: "Holidays",
      text: "Back in January.\nUrgent: call +43 1 234.",
      keep: [],
    };
    const { text, needs } = vacationText(vacation, ["me@x.org"], "\n");
    const written = writeScript(
      withRequires(setVacation(document, text, vacation), needs),
    );
    expect(written).toContain(
      [
        'require ["fileinto", "imap4flags", "copy", "body", "vacation", "date", "relational"];',
        "# rule:[Automatic reply]",
        'if allof (currentdate :value "ge" "date" "2026-12-20", currentdate :value "le" "date" "2027-01-06")',
        "{",
        '\tvacation :days 1 :subject "Holidays" :addresses "me@x.org" text:',
        "Back in January.",
        "Urgent: call +43 1 234.",
        ".",
        ";",
        "}",
        "# rule:[Newsletters]",
      ].join("\n"),
    );
    const reread = parseScript(written);
    expect(autoReplyOf(reread)).toEqual({
      enabled: true,
      start: "2026-12-20",
      end: "2027-01-06",
      subject: "Holidays",
      text: "Back in January.\nUrgent: call +43 1 234.",
      contactsOnly: false,
    });
    expect(filterChunks(reread)).toHaveLength(4);

    const off = { ...vacation, enabled: false };
    const offText = vacationText(off, ["me@x.org"], "\n");
    const switchedOff = parseScript(
      writeScript(setVacation(reread, offText.text, off)),
    );
    expect(autoReplyOf(switchedOff)).toMatchObject({
      enabled: false,
      subject: "Holidays",
      start: "2026-12-20",
    });
  });
});

describe("editing the list", () => {
  const document = parseScript(SCRIPT);
  const added = ruleText(rule({ name: "Anna" }), "\n");

  it("inserts a rule at a place, or last", () => {
    const first = writeScript(
      insertFilter(document, 0, {
        kind: "rule",
        text: added.text,
        rule: rule(),
      }),
    );
    expect(first).toContain(
      '# rule:[Anna]\nif header :contains "from" "anna@example.org"\n{\n\taddflag "\\\\Seen";\n}\n# rule:[Newsletters]',
    );
    const last = writeScript(
      insertFilter(document, undefined, {
        kind: "rule",
        text: added.text,
        rule: rule(),
      }),
    );
    expect(last).toBe(`${SCRIPT}${added.text}\n`);
    const unterminated = parseScript("keep;");
    expect(
      writeScript(
        insertFilter(unterminated, undefined, {
          kind: "rule",
          text: added.text,
          rule: rule(),
        }),
      ),
    ).toBe(`keep;\n${added.text}\n`);
  });

  it("removes a rule with its line end", () => {
    const written = writeScript(removeFilter(document, 1));
    expect(written).not.toContain("Boss");
    expect(written).toContain("\tstop;\n}\n/* hand-written */");
  });

  it("reorders the rules in place", () => {
    const reordered = parseScript(
      writeScript(reorderFilters(document, [3, 0, 1, 2])),
    );
    expect(
      filterChunks(reordered).map((f) =>
        f.kind === "rule" ? (f.rule.name ?? "size") : "custom",
      ),
    ).toEqual(["size", "Newsletters", "Boss", "custom"]);
  });

  it("adds a require when the script has none", () => {
    const empty = parseScript("");
    const withRule = insertFilter(empty, undefined, {
      kind: "rule",
      text: ruleText(
        rule({ actions: { ...NO_ACTIONS, moveTo: folderId("X") } }),
        "\r\n",
      ).text,
      rule: rule(),
    });
    expect(writeScript(withRequires(withRule, ["fileinto"]))).toBe(
      'require "fileinto";\r\nif header :contains "from" "anna@example.org"\r\n{\r\n\tfileinto "X";\r\n}\r\n',
    );
  });
});
